using System.Windows.Media.Imaging;

namespace Veil.Tor;

/// The onion image shown in Tor windows (embedded as text so no extra resource file is needed).
public static class TorLogo
{
    const string Base64 = "";

    public static string DataUri => "data:image/png;base64," + Base64;

    static BitmapImage bmp;
    public static BitmapImage Bitmap()
    {
        if (bmp != null) return bmp;
        var b = new BitmapImage();
        b.BeginInit();
        b.CacheOption = BitmapCacheOption.OnLoad;
        b.StreamSource = new MemoryStream(Convert.FromBase64String(Base64));
        b.EndInit();
        b.Freeze();
        return bmp = b;
    }
}
